    const long LIMIT = 200;
    bool active = false;
    string currency = "TRY";
    [System.CLSCompliant(false)]
    double Quote(
        double miktar_ö,
        int rate
    ) {
        return miktar_ö * rate;
    }
    string label = "İzmir 😀";
} // end

class Policy {
    const long LIMIT = 100;
    bool active = true;
    int obsolete = 7;
    [System.Obsolete]
    long Quote(
        long miktar,
        int rate
    ) {
        return miktar * rate;
    }
    string label = "İstanbul 😀";
}

