import java.util.Set;
class Policy {
    static final long LIMIT = 200;
    boolean active = false;
    String currency = "TRY";
    @SuppressWarnings("unused")
    double quote(
        double miktar_ö,
        int rate
    ) {
        return miktar_ö * rate;
    }
    String label = "İzmir 😀";
} // end

class Policy {
    static final long LIMIT = 100;
    boolean active = true;
    int obsolete = 7;
    @Deprecated
    long quote(
        long miktar,
        int rate
    ) {
        return miktar * rate;
    }
    String label = "İstanbul 😀";
}

